mapper.select:
SELECT t.inventory_detail_id AS inventoryId, t.flowCount AS flowCount, t.netQty AS netQty, t.firstBefore AS firstBefore, t.lastAfter AS lastAfter FROM ( SELECT op.inventory_detail_id, COUNT(*) OVER (PARTITION BY op.inventory_detail_id) AS flowCount, SUM(CASE WHEN op.type = 1 THEN op.quantity WHEN op.type = 2 THEN -op.quantity WHEN op.type = 5 THEN op.quantity ELSE 0 END) OVER (PARTITION BY op.inventory_detail_id) AS netQty, FIRST_VALUE(op.before_qty) OVER ( PARTITION BY op.inventory_detail_id ORDER BY op.id ASC ) AS firstBefore, FIRST_VALUE(op.after_qty) OVER ( PARTITION BY op.inventory_detail_id ORDER BY op.id DESC ) AS lastAfter, ROW_NUMBER() OVER ( PARTITION BY op.inventory_detail_id ORDER BY op.id ASC ) AS rn FROM o_goods_inventory_operation op WHERE op.status = 1
AND op.merchant_id = #{merchantId,jdbcType=BIGINT}
AND op.inventory_detail_id IN
#{id}
) t WHERE t.rn = 1
